node.interaction_0_script_to_test_if_interact:
function Dot(u, v)
{
	return u[0] * v[0] + u[1] * v[1];
}

function Distance(a, b)
{
	local v = [a[0] - b[0], a[1] - b[1]];
	return sqrt(Dot(v, v));
}

function IsInteractionAvailable(so_self, so_activator)
{
	if (!IAP_IsItemPurchased("DLC2"))
		return false;

	local drone_pos = StageObject_GetPosition(so_self);
	local door_pos = StageObject_GetPositionWithOffset(so_self, -60, 0, 0);
	local pos = StageObject_GetPosition(so_activator);

	local vec_drone_door = [door_pos[0] - drone_pos[0], door_pos[1] - drone_pos[1]];
	local vec_player_door = [door_pos[0] - pos[0], door_pos[1] - pos[0]];

	local dot = Dot(vec_drone_door, vec_player_door);

	local can_interact = false;
	if (dot > 0)
		can_interact = Distance(pos, drone_pos) < 60;
	else
		can_interact = Distance(pos, door_pos) < 60;

	if (!can_interact)
		return false;

	local quest_id = "quests/hidden-archipelago.nut";
	if (Game_IsQuestCompleted(quest_id))
		return true;

	if (!Game_IsQuestCurrent(quest_id))
		return false;

	return true;
}

node.interaction_0_script_to_run_on_interacti:
function OnInteraction(so_self, so_activator)
{
	local quest_id = "quests/hidden-archipelago.nut";
	local phase_id = Game_GetQuestPhaseId(quest_id);

	if (phase_id == "PHASE_INVESTIGATE_SIGNAL")
	{
		Actor_SetInteractionEnabled(so_self, "use", true);
		Game_SendQuestPhaseCommandWord(quest_id, phase_id, "activate");
		return;
	}

	if (phase_id == "PHASE_GO_TO_DRONE_DEPOT")
	{
		Actor_SetInteractionEnabled(so_self, "use", true);
		Game_SendQuestPhaseCommandWord(quest_id, phase_id, "activate");
		return;
	}

	Game_SetStagePointOfInterestCompleted(so_self);

	Game_SetCinemaMode(true);
	local pos = StageObject_GetPosition(so_self);
	Actor_QueueActionMove(so_activator, pos[0], pos[1]);

	local command = Command_Create("activate");
	Command_SetStageObjectReference(command, so_activator);
	Actor_QueueActionSendCommand(so_activator, so_self, command, 0);
	Command_Delete(command);

	return;

	Actor_QueueActionPlayAnimation(so_self, "propellers_start", false);
	Actor_QueueActionPlayAnimation(so_self, "door_closing", false);

	local so_drone = so_self;

	local script = @"
		StageObject_SetParentButRetainStageTransform(so_self, $so_drone);
		Actor_InteractWithInteraction($so_drone, so_self, ""fly_away"");
	";
	script = string_replace(script, "$so_drone", so_drone.tostring());
	Actor_QueueActionRunScript(so_activator, script);
}

node.interaction_1_script_to_run_on_interacti:
function OnInteraction(so_self, so_activator)
{
	Actor_SetActorFlag(so_self "STATIC", false);
	Actor_PlayAnimation(so_self, "propellers_run");
	local kvs = StageObject_GetKeyValueStore(so_self);
	Actor_QueueActionMoveAlongKeyValueStorePath(so_self, kvs, "fly_away_path");

}

